from langchain_core.tools import tool
from pydantic import BaseModel, Field

class SearchInput(BaseModel):
    query: str = Field(description="搜索关键词")
    max_results: int = Field(default=5, ge=1, le=20, description="最大返回数1-20")

@tool(args_schema=SearchInput)
def search(query: str, max_results: int) -> str:
    """搜索互联网"""
    results = [f"结果{i}: 关于 {query} 的内容" for i in range(1, max_results + 1)]
    return "\n".join(results)

print(search.invoke({"query": "python", "max_results": 3}))
try:
    print(search.invoke({"query": "test", "max_results": 100}))
except Exception as e:
    print(f"校验失败(预期): {e}")

